from pathlib import Pathimport numpy as npimport pandas as pdROOT = Path(__file__).resolve().parent.parentRESULTS = ROOT / "results"PROCESSED = ROOT / "data" / "processed"daily = pd.read_csv(    PROCESSED / "multisat_2024_recent_daily_decay_kp.csv")behavior = pd.read_csv(    RESULTS / "multisat_2024_orbital_behavior.csv")# Use the same satellite ID format in both files.daily["norad_id"] = pd.to_numeric(    daily["norad_id"], errors="coerce")behavior["norad_id"] = pd.to_numeric(    behavior["norad_id"], errors="coerce")daily["decay_km_day"] = pd.to_numeric(    daily["decay_km_day"], errors="coerce")for column in ["storm_day", "suspicious_change", "usable_decay"]:    daily[column] = (        daily[column].astype(str).str.lower() == "true"    )daily = daily.merge(    behavior[["norad_id", "behavior"]],    on="norad_id",    how="left",    validate="many_to_one")rows = []for norad, g in daily.groupby("norad_id"):    all_valid = g.dropna(subset=["decay_km_day"])    filtered = all_valid[all_valid["usable_decay"]]    def storm_difference(data):        storm = data.loc[            data["storm_day"], "decay_km_day"        ]        nonstorm = data.loc[            ~data["storm_day"], "decay_km_day"        ]        if len(storm) < 2 or len(nonstorm) < 2:            return np.nan        return storm.mean() - nonstorm.mean()    rows.append({        "norad_id": norad,        "satellite_name": g["satellite_name"].iloc[0],        "altitude_band": g["altitude_band"].iloc[0],        "behavior": g["behavior"].iloc[0],        "total_decay_days": len(all_valid),        "flagged_days": int(            all_valid["suspicious_change"].sum()        ),        "usable_days": len(filtered),        "removed_fraction": (            1 - len(filtered) / len(all_valid)            if len(all_valid) else np.nan        ),        "unfiltered_difference_km_day":            storm_difference(all_valid),        "filtered_difference_km_day":            storm_difference(filtered),    })result = pd.DataFrame(rows)result["difference_shift_km_day"] = (    result["filtered_difference_km_day"]    - result["unfiltered_difference_km_day"])result.to_csv(    RESULTS / "multisat_2024_filter_audit.csv",    index=False)print("\nFILTERING BY ALTITUDE BAND:")print(    result.groupby("altitude_band").agg(        satellites=("norad_id", "size"),        total_days=("total_decay_days", "sum"),        flagged_days=("flagged_days", "sum"),        median_removed_fraction=(            "removed_fraction", "median"        ),    ).to_string())print("\nFILTERING BY ORBITAL BEHAVIOR:")print(    result.groupby("behavior").agg(        satellites=("norad_id", "size"),        median_removed_fraction=(            "removed_fraction", "median"        ),    ).to_string())print("\nSTORM DIFFERENCES BEFORE AND AFTER FILTERING:")print(    result.groupby("altitude_band").agg(        unfiltered_median=(            "unfiltered_difference_km_day", "median"        ),        filtered_median=(            "filtered_difference_km_day", "median"        ),        satellites_with_unfiltered=(            "unfiltered_difference_km_day", "count"        ),        satellites_with_filtered=(            "filtered_difference_km_day", "count"        ),    ).to_string())print("\nLOW-ALTITUDE SATELLITES:")print(    result[result["altitude_band"] == "200-350 km"][        [            "satellite_name",            "behavior",            "flagged_days",            "usable_days",            "unfiltered_difference_km_day",            "filtered_difference_km_day",        ]    ].to_string(index=False))print("\nSaved: results/multisat_2024_filter_audit.csv")